<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request} from './service';import {useRoute,useRouter} from 'vue-router';import {useUserStoreHook} from '@/store/modules/user';import LinIcon from './LinIcon.vue';
const route=useRoute(),router=useRouter(),me=useUserStoreHook(),username=ref('admin'),password=ref(''),busy=ref(false),error=ref('');
async function login(){busy.value=true;error.value='';try{await me.loginByUsername({username:username.value,password:password.value});const next=String(route.query.next||'');if(/^\/workspace(?:\/[a-z]+)?$/.test(next))location.href=next;else await router.push(me.role===1?'/room':'/account');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(async()=>{try{const s=await request('/api/status');if(s.setup)error.value='站主账号尚未配置，请在服务器运行 npm run owner:init 后再登录。';}catch(e){error.value=e.message;}});
const registering=ref(false),name=ref(''),reason=ref(''),answer=ref(''),captcha=ref(null),success=ref('');
async function refreshCaptcha(){captcha.value=await request('/api/register/captcha');answer.value='';}
async function toggle(){registering.value=!registering.value;error.value='';success.value='';if(registering.value){username.value='';await refreshCaptcha();}}
async function register(){busy.value=true;error.value='';try{const r=await request('/api/register','POST',{username:username.value,password:password.value,name:name.value,reason:reason.value,captchaId:captcha.value?.id,captchaAnswer:answer.value});success.value=r.message;registering.value=false;password.value='';captcha.value=null;}catch(e){error.value=e.message;await refreshCaptcha();}finally{busy.value=false;}}
</script>
<template><main class="lin-login"><section class="login-picture"><img src="/assets/landscape-study.webp" alt="留一盏灯，给尚未写完的故事"/><a href="/">← 回到 Lin 的随手记</a><div><span>THE OTHER SIDE OF THE NOTEBOOK</span><h1>故事还在继续，<br/>你的座位一直在。</h1><p>Keep a little room for wonder.</p></div><small>Lin’s Studio · 让灵感有处安放</small></section><section class="login-entry"><div class="login-entry-inner"><span class="login-monogram">L✦</span><span class="studio-eyebrow">WELCOME BACK</span><h2>{{registering?'申请读者账号':'登录 Lin 的随手记'}}</h2><p>写一点日常，整理一些喜欢的瞬间。</p><p v-if="success" role="status" class="register-success">{{success}}</p><form @submit.prevent="registering?register():login()"><label>账号<el-input v-model="username" :placeholder="registering?'3–32 位小写字母、数字、下划线':'账号'" autocomplete="username" required maxlength="32"/></label><label>密码<el-input v-model="password" placeholder="密码" type="password" show-password :autocomplete="registering?'new-password':'current-password'" :minlength="registering?10:undefined" required/></label><template v-if="registering"><label>昵称<el-input v-model="name" required maxlength="80" placeholder="怎么称呼你？"/></label><label>申请说明<el-input v-model="reason" type="textarea" required minlength="2" maxlength="500" placeholder="说说你为什么想加入吧"/></label><label>图片验证码 <span class="captcha-row"><img v-if="captcha" :src="captcha.image" alt="五位数字验证码"/><button type="button" @click="refreshCaptcha">换一张</button></span><el-input v-model="answer" required maxlength="5" inputmode="numeric" placeholder="输入图中的五位数字"/></label><p>密码至少 10 位。申请需经站主审核，通过后才可登录。</p></template><p v-if="error" class="login-error" role="alert">{{error}}</p><el-button native-type="submit" type="primary" :loading="busy">{{registering?'提交注册申请':'登录'}} <LinIcon name="arrow" :size="18"/></el-button></form><button type="button" class="register-toggle" @click="toggle">{{registering?'已有账号？返回登录':'还没有账号？申请加入 →'}}</button><div class="login-footnote"><LinIcon name="user" :size="15"/>读者注册需站主审核。账号用于留言与个人资料，阅读无需登录。</div></div></section></main></template>
<style scoped>.captcha-row{display:flex;align-items:center;gap:16px;margin-top:12px}.captcha-row img{width:180px;height:auto;border-radius:10px}.captcha-row button,.register-toggle{border:0;background:none;color:#8270a2;cursor:pointer;font-size:12px}.register-toggle{margin-top:22px}.register-success{padding:15px;background:#eaf4e9;border-radius:12px;color:#466551!important}.lin-login{display:grid;grid-template-columns:1fr 1fr;min-height:100vh;background:var(--studio-panel)}.login-picture{position:relative;background:#232435;overflow:hidden;color:#fff;min-height:100vh}.login-picture>img{position:absolute;width:100%;height:100%;object-fit:cover;opacity:.63;filter:saturate(.7)}.login-picture::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#191825bb,transparent 80%)}.login-picture>a{position:absolute;top:38px;left:40px;z-index:2;font-size:12px;color:#e4e1db}.login-picture>div{position:absolute;bottom:125px;left:10%;z-index:2}.login-picture>div>span{font-size:8px;letter-spacing:2.5px;color:#c3bfb7}.login-picture h1{font-size:clamp(30px,3vw,45px);line-height:1.5;font-weight:500;margin:23px 0}.login-picture p{font:italic 19px Georgia,serif;color:#d1cabb}.login-picture>small{position:absolute;bottom:40px;left:10%;z-index:2;font-size:10px;letter-spacing:1px;color:#c4c2bc}.login-entry{display:grid;place-items:center;padding:60px 35px}.login-entry-inner{max-width:345px;width:100%}.login-monogram{display:block;color:#8177aa;font:36px Georgia,serif;margin-bottom:52px}.login-entry .studio-eyebrow{font-size:9px;letter-spacing:3px}.login-entry h2{font-size:27px;font-weight:550;margin:15px 0}.login-entry p{font-size:12px;color:var(--studio-muted);line-height:1.8}.login-entry form{margin-top:35px}.login-entry label{display:block;font-size:12px;margin-bottom:22px}.login-entry .el-input{margin-top:10px}.login-entry :deep(.el-input__wrapper){min-height:42px;background:var(--studio-bg);box-shadow:0 0 0 1px var(--studio-line)}.login-entry form>.el-button{width:100%;height:44px;letter-spacing:2px}.login-entry form>.el-button svg{margin-left:20px}.login-footnote{font-size:9px;line-height:1.8;color:var(--studio-muted);border-top:1px solid var(--studio-line);padding-top:22px;margin-top:32px;display:flex;gap:8px;align-items:center}.login-entry .login-error{color:#c97373;margin-bottom:15px}@media(max-width:760px){.lin-login{grid-template-columns:1fr}.login-picture{min-height:250px}.login-picture>div{bottom:50px;left:7%}.login-picture h1{font-size:25px;margin:15px 0}.login-picture>div>span{font-size:6px}.login-picture>a{top:20px;left:7%;font-size:10px}.login-picture p,.login-picture>small{display:none}.login-entry{padding:35px 28px}.login-monogram{margin-bottom:20px;font-size:26px}.login-entry h2{font-size:25px}.login-entry form{margin-top:25px}}</style>
